default_placeholders := {"changeme", "default", "admin", "password", "123456", "empty"}
empty_values := {"", " ", "  ", "   ", "\t"}

is_empty_value(value) {
    value.ir_type == "String"
    value.value == empty_values[_]
} else {
    value.ir_type == "Null"
} else {
    value.ir_type == "Undef"
} else {
